import RNA
import random

target = ".....(((((((.(((((....)))).)))(((((.((..((((....))))..(((((......)))))..)).))))))))))...................."
base = "AAAAAGGGGGGGAGGGGCGAAAGCCCACCCGGGGGAGGAAGGGCGAAAGCCCAAGGGGGAAAAAACCCCCAACCACCCCCCCCCCAAAAAAAAAAAAAAAAAAAA"

comp = {'A':'U','U':'A','G':'C','C':'G'}

# target pairs
target_pairs = [(5,84),(6,83),(7,82),(8,81),(9,80),(10,29),(11,28),(13,27),(14,25),(15,24),(16,23),(17,22),
                (30,79),(31,78),(32,77),(33,76),(34,75),(36,73),(37,72),(40,51),(41,50),(42,49),(43,48),
                (54,69),(55,68),(56,67),(57,66),(58,65)]

def dist(s):
    fc=RNA.fold_compound(s)
    mfe,_=fc.mfe()
    return RNA.bp_distance(mfe,target)

best=(99,None)
random.seed(1)
for it in range(20000):
    seq=list(base)
    # randomly mutate some positions in window 5-30 and 70-84, preserving pair complementarity
    for p in [5,6,7,8,9,10,11,13,14,15,16,17,30,31,32,33,34,36,37,40,41,42,43,54,55,56,57,58]:
        if random.random()<0.3:
            seq[p]=random.choice('ACGU')
    # set complements
    for i,j in target_pairs:
        seq[j]=comp.get(seq[i],seq[j]) if seq[i] in 'ACGU' else seq[j]
        # allow some wobble
        if random.random()<0.1 and seq[i] in 'GU':
            seq[j]=comp[seq[i]] if seq[i] in 'AC' else random.choice(['C','U'])
    # random loops
    for k in range(4): seq[18+k]=random.choice('ACGU')
    for k in range(4): seq[44+k]=random.choice('ACGU')
    for k in range(6): seq[59+k]=random.choice('ACGU')
    s=''.join(seq)
    d=dist(s)
    if d<best[0]:
        best=(d,s)
        print("new best", d, s)
    if d==0:
        print("SOLVED", s); break
print("FINAL best", best)
